// === Tab: mySketch ===
/************************
 * LEVELS
 * by twitter.com/mattywillo_
 * made for twitter.com/sableRaph's #WCCChallenge topic: levels
 * jump on the birbs nest discord to join the challenge and to vote on future topics:
 * discord.gg/S8c7qcjw2b
 ************************/

//levels and layers are the same change my mind

let {PI} = Math;

let res,sh,t=0;
let regen = true;

//comment/uncomment lines to change possible palettes
let pairs = [
  [[247,37,133],[58,12,163]],
  [[239,71,111],[255,209,102]],
  [[6,214,160],[17,138,178]],
  [[116,0,184],[128,255,219]],
  [[255,10,84],[247,202,208]],
  // [[217,237,146],[52,160,164]],
  // [[183,9,76],[0,145,173]],
].map(x=>x.map(y=>y.map(z=>z/255)));

//comment/uncomment lines to change possible spacing, if there's less than 2 lines uncommented the whole thing breaks
let modes = [
  // (i,j,s)=>0,
  // (i,j,s)=>i*s,
  // (i,j,s)=>j*s,
  (i,j,s)=>i*s*2,
  (i,j,s)=>j*s*2,
  (i,j,s)=>i*s*3,
  (i,j,s)=>j*s*3,
]

const shaderSrc = [`
attribute vec3 aPosition;
attribute vec4 aVertexColor;
attribute vec2 aTexCoord;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
varying vec4 vColor;
varying vec2 vTexCoord;
varying vec3 vPos;
void main() {
  gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.);
  vColor = aVertexColor;
  vTexCoord = aTexCoord;
  vPos = aPosition;
}
`,`
precision highp float;
#define PI `+PI+`

//some noise from this gist https://gist.github.com/patriciogonzalezvivo/670c22f3966e662d2f83
float mod289(float x){return x - floor(x * (1.0 / 289.0)) * 289.0;}
vec4 mod289(vec4 x){return x - floor(x * (1.0 / 289.0)) * 289.0;}
vec4 perm(vec4 x){return mod289(((x * 34.0) + 1.0) * x);}

float noise(vec3 p){
    vec3 a = floor(p);
    vec3 d = p - a;
    d = d * d * (3.0 - 2.0 * d);

    vec4 b = a.xxyy + vec4(0.0, 1.0, 0.0, 1.0);
    vec4 k1 = perm(b.xyxy);
    vec4 k2 = perm(k1.xyxy + b.zzww);

    vec4 c = k2 + a.zzzz;
    vec4 k3 = perm(c);
    vec4 k4 = perm(c + 1.0);

    vec4 o1 = fract(k3 * (1.0 / 41.0));
    vec4 o2 = fract(k4 * (1.0 / 41.0));

    vec4 o3 = o2 * d.z + o1 * (1.0 - d.z);
    vec2 o4 = o3.yw * d.x + o3.xz * (1.0 - d.x);

    return o4.y * d.y + o4.x * (1.0 - d.y);
}

//straight from iq https://www.shadertoy.com/view/ttcyRS
vec3 oklab_mix( vec3 colA, vec3 colB, float h )
{
    // https://bottosson.github.io/posts/oklab
    const mat3 kCONEtoLMS = mat3(
         0.4121656120,  0.2118591070,  0.0883097947,
         0.5362752080,  0.6807189584,  0.2818474174,
         0.0514575653,  0.1074065790,  0.6302613616);
    const mat3 kLMStoCONE = mat3(
         4.0767245293, -1.2681437731, -0.0041119885,
        -3.3072168827,  2.6093323231, -0.7034763098,
         0.2307590544, -0.3411344290,  1.7068625689);

    // rgb to cone (arg of pow can't be negative)
    vec3 lmsA = pow( kCONEtoLMS*colA, vec3(1.0/3.0) );
    vec3 lmsB = pow( kCONEtoLMS*colB, vec3(1.0/3.0) );
    // lerp
    vec3 lms = mix( lmsA, lmsB, h );
    // gain in the middle (no oaklab anymore, but looks better?)
 lms *= 1.0+0.2*h*(1.0-h);
    // cone to rgb
    return kLMStoCONE*(lms*lms*lms);
}

uniform float h,af,sc;
uniform vec3 c0,c1,c2,c3;
uniform vec2 off, noff;
varying vec4 vColor;
varying vec2 vTexCoord;
varying vec3 vPos;
uniform float t,l;
void main() {
  vec3 col = oklab_mix(oklab_mix(c0, c1, vPos.x*.5+.5), oklab_mix(c2,c3,vPos.z*.5+.5), h);
  float a = smoothstep(.45+h*.25, .5+h*.25, noise(vec3((vPos.xz+off)*sc, h*2.)))-(vPos.y*.5+.5)*af;
  gl_FragColor = vec4(col, a);
}
`];

const geo = (size, thickness, slices, off, palette, alp, sc) => {
  spacing = (size-thickness*slices)/(slices-1);
  palette.forEach((p,i)=>sh.setUniform("c"+i, p));
  sh.setUniform("off", off);
  sh.setUniform("af", alp);
  sh.setUniform("sc", sc);
  for(let i = 0; i < slices; i++) {
    sh.setUniform("h", i/slices);
    push();
    translate(0, -size*.5+thickness*.5+i*thickness+i*spacing, 0);
    box(size, thickness, size);
    pop();
  }
}

let fns,size,slices,sliceSize,palette,af,sc;

function draw() {
  background(0);
  resetShader();

  fill(0,0,0,0);
  shader(sh);
  noStroke();

  if(regen)  {
    //this is the dumbest line of code i've ever written but i'm writing it while the stream is on so it is what it is
    fns = [...Array(20)].reduce((acc,_,i)=>{let r = (Math.random()*modes.length)|0; return (acc.indexOf(r)==-1)?[...acc,r]:acc},[]).slice(0,2).map(i=>modes[i]);
    size  = random([.25,.5,1]);
    slices = [...Array(9*9)].map(i=>random(2,20));
    sliceSize = [...Array(9*9)].map(i=>random(.1,.3));
    palette = [...Array(9*9)].map(i=>[...random(pairs), ...random(pairs)]);
    af = random(.2,.9);
    sc = random(4,7);
    noff = [random(0,10), random(0,10)];
    regen = false;
  }
  for(let i = -4; i < 4; i++)
  for(let j = -4; j < 4; j++) {
    push();
    // translate(fns[0](i,j,size), fns[1](i,j,size), fns[2](i,j,size));
    translate(fns[0](i,j,size), 0, fns[1](i,j,size));
    scale(size,size,size);
    geo(1., sliceSize[i+j+8], slices[i+j+8], [i+noff[0], j+noff[1]], palette[i+j+8], af, sc);
    pop();
  }

  if((t+=deltaTime/1000)>3){
    t = 0;
    regen = true;
  }
}

function setup() {
  res = Math.min(1112, 834);
  createCanvas(1112, 834, WEBGL);
  colorMode(RGB, 1, 1, 1, 1);
  ortho(-1,  1, 1, -1, 0, 10);
  camera(1,1,1,0,0,0,0,1,0);
  smooth();
  setAttributes("depth", false);
  sh = new p5.Shader(undefined, ...shaderSrc);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed() {
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

